def keep_latest_submission(apps, schema_editor):
    """Collapse multiple attempts into one row per (assignment, student).

    Keeps the newest attempt (that is the one being graded), sets created_at to the
    time of the first attempt, and removes the older rows. Their files stay on disk.
    """
    Submission = apps.get_model('courses', 'Submission')
    seen = {}
    for s in Submission.objects.order_by('assignment_id', 'student_id', '-submitted_at', '-id'):
        key = (s.assignment_id, s.student_id)
        if key not in seen:
            seen[key] = s
            s.created_at = s.submitted_at
            s.save(update_fields=['created_at'])
        else:
            keep = seen[key]
            if s.submitted_at < keep.created_at:
                keep.created_at = s.submitted_at
                keep.save(update_fields=['created_at'])
            s.delete()


